{
  "table": {
    "name": "disp",
    "purpose": "Disposition table linking clients to bank accounts, specifying each client's role on the account (owner or disponent/authorized user). One row per client-account relationship. This matches the classic Berka (PKDD'99) financial dataset."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "disp_id",
      "description": "Primary key of the disposition record; unique surrogate identifier for each client-account relationship.",
      "status": "resolved"
    },
    "col_002": {
      "role": "identifier",
      "name": "client_id",
      "description": "Foreign key to client (client.col_001). One-to-one join accepted by statistics; each disposition belongs to exactly one client.",
      "status": "resolved"
    },
    "col_003": {
      "role": "identifier",
      "name": "account_id",
      "description": "Foreign key to account (account.col_001). Many dispositions can point to the same account (4500 distinct accounts for 5369 rows), i.e. an account can have multiple associated clients.",
      "status": "resolved"
    },
    "col_004": {
      "role": "code",
      "name": "disp_type",
      "description": "Type of disposition: 'OWNER' (account holder, 4500 rows) or 'DISPONENT' (authorized user/additional person on the account, 869 rows).",
      "status": "resolved"
    }
  }
}
